=====CreateInvoiceLogic=====
package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * POST /api/projects/{projectId}/invoices — add an invoice for the given amount to an existing
 * project, echo back the saved row. A missing amount or an unknown project is rejected with 400 and
 * never persisted.
 */
public class CreateInvoiceLogic {

    public void service(@HttpPathParameter("projectId") String projectId,
            @RequestBody NewInvoice newInvoice, ProjectRepository projects,
            InvoiceRepository invoices, ObjectResponse<InvoiceView> response) {
        BigDecimal amount = newInvoice.getAmount();
        if (amount == null) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An amount is required");
        }
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "An amount greater than zero is required");
        }
        Long id = Long.valueOf(projectId);
        projects.findById(id).orElseThrow(
                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing project is required"));
        Invoice saved = invoices.save(new Invoice(id, amount));
        response.send(new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(), saved.getStatus(),
                saved.getIssuedDate() == null ? null : saved.getIssuedDate().toString(),
                saved.getDueDate() == null ? null : saved.getDueDate().toString()));
    }
}
=====LineItemView=====
package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * A line item as the UI shows it: its id, the owning invoice's id, the description, the quantity, the
 * unit that quantity is measured in and the unit price. The UI works out each line's amount and the
 * invoice amount from these.
 */
public class LineItemView {

    private final Long id;
    private final Long invoiceId;
    private final String description;
    private final int quantity;
    private final String unit;
    private final BigDecimal unitPrice;

    public LineItemView(Long id, Long invoiceId, String description, int quantity, String unit,
            BigDecimal unitPrice) {
        this.id = id;
        this.invoiceId = invoiceId;
        this.description = description;
        this.quantity = quantity;
        this.unit = unit;
        this.unitPrice = unitPrice;
    }

    public Long getId() {
        return id;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public String getDescription() {
        return description;
    }

    public int getQuantity() {
        return quantity;
    }

    public String getUnit() {
        return unit;
    }

    public BigDecimal getUnitPrice() {
        return unitPrice;
    }
}
=====ListLineItemsLogic=====
package net.officefloor.hq.app;

import java.util.List;
import java.util.stream.Collectors;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/invoices/{invoiceId}/lineitems — the line items an invoice charges for, oldest first.
 * The UI works out each line's total and the invoice amount (the sum of them) from these.
 */
public class ListLineItemsLogic {

    public void service(@HttpPathParameter("invoiceId") String invoiceId,
            LineItemRepository lineItems, ObjectResponse<List<LineItemView>> response) {
        Long id = Long.valueOf(invoiceId);
        List<LineItemView> views = lineItems.findByInvoiceIdOrderByIdAsc(id).stream()
                .map(li -> new LineItemView(li.getId(), li.getInvoiceId(), li.getDescription(),
                        li.getQuantity(), li.getUnit(), li.getUnitPrice()))
                .collect(Collectors.toList());
        response.send(views);
    }
}

